package productspecvalueservicelogic
import (
	"context"; "errors"; "fmt"; "strings"
	logiccommon "github.com/feihua/zero-admin/rpc/pms/internal/logic/common"; "github.com/feihua/zero-admin/rpc/pms/internal/svc"; "github.com/feihua/zero-admin/rpc/pms/pmsclient"; "github.com/zeromicro/go-zero/core/logc"; "github.com/zeromicro/go-zero/core/logx")

type AddProductSpecValueLogic struct { ctx context.Context; svcCtx *svc.ServiceContext; logx.Logger }
func NewAddProductSpecValueLogic(ctx context.Context, svcCtx *svc.ServiceContext) *AddProductSpecValueLogic { return &AddProductSpecValueLogic{ctx:ctx, svcCtx:svcCtx, Logger:logx.WithContext(ctx)} }
func (l *AddProductSpecValueLogic) AddProductSpecValue(in *pmsclient.AddProductSpecValueReq) (*pmsclient.AddProductSpecValueResp, error) { currentScope, err := logiccommon.ResolveWriteScope(l.ctx, l.svcCtx.DB, in.Scope, in.CreateBy); if err != nil { return nil, err }; if err := logiccommon.EnsureScopedSpecExists(l.ctx, l.svcCtx.DB, currentScope, in.SpecId, "当前主体无权在该商品规格下创建规格值"); err != nil { return nil, err }; var count int64; if err := l.svcCtx.DB.WithContext(l.ctx).Table("pms_product_spec_value").Where("is_deleted = 0 AND spec_id = ? AND value = ? AND platform_id = ? AND tenant_id = ? AND merchant_id = ?", in.SpecId, strings.TrimSpace(in.Value), currentScope.PlatformID, currentScope.TenantID, currentScope.MerchantID).Count(&count).Error; err != nil { logc.Errorf(l.ctx, "校验商品规格值重复失败,参数:%+v,异常:%s", in, err.Error()); return nil, errors.New("校验商品规格值重复失败") }; if count > 0 { return nil, errors.New(fmt.Sprintf("商品规格值：%s,已存在", in.Value)) }; item := map[string]interface{}{"spec_id":in.SpecId,"value":strings.TrimSpace(in.Value),"sort":in.Sort,"status":in.Status,"create_by":in.CreateBy,"platform_id":currentScope.PlatformID,"tenant_id":currentScope.TenantID,"merchant_id":currentScope.MerchantID}; if err := l.svcCtx.DB.WithContext(l.ctx).Table("pms_product_spec_value").Create(item).Error; err != nil { logc.Errorf(l.ctx, "添加商品规格值失败,参数:%+v,异常:%s", item, err.Error()); return nil, errors.New("添加商品规格值失败") }; return &pmsclient.AddProductSpecValueResp{Pong:"ok"}, nil }
